<div :class="['ops-page',platform?'brand-'+platform.slug:'ops-holding']"><aside class="ops-sidebar"><RouterLink to="/admin" class="ops-logo"><PlatformIcon :name="platform?.icon||'heart'" :size="30"/><span>{{platform?.name||'مهرگان پارس'}}<small>{{platform?.eyebrow||'مدیریت هولدینگ'}}</small></span></RouterLink><div class="ops-context"><i></i>{{ t("در حال مدیریت ") }}{{platform?.name||'هولدینگ مهرگان'}}</div><div class="user-role"><small>{{t('نقش کاربر','User role')}}</small><strong>{{currentAdmin?.role==='owner'?t('مدیر اصلی','Owner'):t('ویرایشگر','Editor')}}</strong><span>{{currentAdmin?.name}}</span></div><span class="ops-nav-label">{{ t("میز کار شما") }}</span><nav aria-label="مدیریت"><RouterLink v-if="tab==='magazine'" to="/admin"><LayoutDashboard :size="18"/>{{ t("نمای کلی") }}</RouterLink><button v-else :class="{active:tab==='overview'}" @click="emit('tab','overview')"><LayoutDashboard :size="18"/>{{ t("نمای کلی") }}</button><template v-if="platform"><button :class="{active:tab==='wallet'}" @click="emit('tab','wallet')"><span>◈</span>{{t('کیف پول','Wallet')}}</button><button :class="{active:tab==='slots'}" @click="emit('tab','slots')"><CalendarDays :size="18"/>{{ t("تقویم و زمان‌بندی") }}</button><button :class="{active:tab==='bookings'}" @click="emit('tab','bookings')"><CalendarDays :size="18"/>{{ t("نوبت‌های مراجعان") }}</button><button :class="{active:tab==='doctors'}" @click="emit('tab','doctors')"><Users :size="18"/>{{ t("متخصصان") }}</button></template><template v-else><RouterLink to="/admin?tab=tickets" :class="{active:tab==='tickets'}"><MessageSquare :size="18"/>{{t('صندوق ارتباط')}}<b>{{state.tickets.filter(t=>t.status==='new').length.toLocaleString('fa-IR')}}</b></RouterLink><RouterLink to="/admin?tab=approvals" :class="{active:tab==='approvals'}"><BookOpenText :size="18"/>{{t('تأیید اصلاحات','Approvals')}}<b>{{governance.reviews.filter(r=>r.status==='pending').length}}</b></RouterLink><RouterLink to="/admin/magazine" :class="{active:tab==='magazine'